import { TempisTimelineItem as TimelineItemDefinition } from "./TempisTimelineOptions";
import { TimelineItem } from "./TimelineItem";
import { doDateRangesOverlap } from "./Utilities";

export class TimelineItemGrouping {
    /** The group name. */
    private readonly _group: string;

    /** The group items. */
    private readonly _items: TimelineItem[];

    /** Creates a new instance of the TimelineItemGrouping class. */
    public constructor(group: string, items: TimelineItemDefinition[]) {
        this._group = group;

        // Create the group items. 
        this._items = items.map((itemDefinition) => new TimelineItem(itemDefinition));

        // Our items should always be sorted by start date.
        this._sortItemsByStartDate();
    }

    /** Gets the group name. */
    public get group(): string {
        return this._group;
    }

    /** Gets the group items. */
    public get items(): TimelineItem[] {
        return this._items;
    }

    /**
     * Gats all items in this group that have a start or end date that lies within the specified range inclusively.
     * @param fromDt The range from date.
     * @param toDt The range to date.
     * @returns All items in this group that have a start or end date that lies within the specified range inclusively.
     */
    public getItemsInRange(fromDt: Date, toDt: Date): TimelineItem[] {
        return this._items.filter((item) => {
            if (item.end) {
                return doDateRangesOverlap(item.start, item.end, fromDt, toDt);
            } else {
                return item.start.getTime() >= fromDt.getTime() && item.start.getTime() <= toDt.getTime();
            }
        });
    }

    /**
     * Sort the group items by start date.
     */
    private _sortItemsByStartDate() : void {
        this._items.sort((a, b) => b.start.getTime() - a.start.getTime());
    }
}